for row in doc.items:

    #frappe.msgprint("Checking 1 ");   

    if not row.batch_no:
        continue

    #frappe.msgprint("Checking 2 ");   


    source = row.s_warehouse or ""
    target = row.t_warehouse or ""

    # Check movement from Under Test warehouse
    if "Under Test" in source:

        # Find Quality Inspection for the batch
        #frappe.msgprint("Checking Batch: " + str(row.batch_no));

        qi = frappe.db.get_value(
            "Quality Inspection",
            {"batch_no": row.batch_no},
            ["name", "status", "docstatus"],
            as_dict=True
        )

        if not qi:
            frappe.throw(
                "No Quality Inspection found for Batch " + row.batch_no
            )

        # Ensure QI is submitted
        if qi.docstatus != 1:
            frappe.throw(
                "Quality Inspection " + qi.name +
                " for Batch " + row.batch_no +
                " must be Submitted before stock movement."
            )

        # Movement to Approved Store
        if "Approved" in target:

            if qi.status != "Accepted":
                frappe.throw(
                    "Batch " + row.batch_no +
                    " cannot move to Approved Store because Quality Inspection " +
                    qi.name + " is not Accepted."
                )
        #frappe.msgprint("Checking Bat: " + str(row.batch_no)); 
        # Movement to Rejected Store
        if "Rejected" in target:

            if qi.status != "Rejected":
                frappe.throw(
                    "Batch " + row.batch_no +
                    " cannot move to Rejected Store because Quality Inspection " +
                    qi.name + " is not Rejected."
                )

        # Prevent movement anywhere else
        if "Approved" not in target and "Rejected" not in target:
            frappe.throw(
                "Batch " + row.batch_no +
                " can only move from Under Test to Approved or Rejected warehouse."
            )

